// a (3 bits) | b (3 bits) | out_or_bitwise (3 bits) | out_or_logical | out_not (6 bits)
// 000       | 000       | 000                     | 0             | 111111
// 000       | 001       | 001                     | 0             | 111110
// 000       | 010       | 010                     | 0             | 111101
// 000       | 011       | 011                     | 0             | 111100
// 000       | 100       | 100                     | 0             | 111011
// 000       | 101       | 101                     | 0             | 111010
// 000       | 110       | 110                     | 0             | 111001
// 000       | 111       | 111                     | 0             | 111000
// 001       | 000       | 001                     | 0             | 110111
// 001       | 001       | 001                     | 0             | 110110
// 001       | 010       | 011                     | 0             | 110101
// 001       | 011       | 011                     | 0             | 110100
// 001       | 100       | 101                     | 0             | 110011
// 001       | 101       | 101                     | 0             | 110010
// 001       | 110       | 111                     | 0             | 110001
// 001       | 111       | 111                     | 0             | 110000
// ... (other combinations follow similar patterns)

module TopModule (
    input  [2:0] a,
    input  [2:0] b,
    output [2:0] out_or_bitwise,
    output      out_or_logical,
    output [5:0] out_not
);

    // Bitwise OR of a and b
    assign out_or_bitwise = a | b;

    // Logical OR of a and b (treats vectors as single logic value)
    assign out_or_logical = (a | b) ? 1 : 0;

    // Invert a and b, place inverse of b in upper half, inverse of a in lower half
    assign out_not = { ~b, ~a };

endmodule

