    input  shift_ena,
    input  count_ena,
    input  data,
    output reg [3:0] q
);

// Initialize q to 4'b0000 on reset
initial begin
    q = 4'b0000;
end

always @(posedge clk) begin
    if (shift_ena) begin
        q <= {data, q[3:1]};
    end else if (count_ena) begin
        q <= q - 1;
    end
end

endmodule

module TopModule (
    input  [4:0] a,
    input  [4:0] b,
    input  [4:0] c,
    input  [4:0] d,
    input  [4:0] e,
    input  [4:0] f,
    output [7:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z
);

    // Concatenate all input vectors and add two 1 bits at the LSB
    wire [31:0] data = {a, b, c, d, e, f, 2'b01};

    // Split the 32-bit data into four 8-bit outputs
    assign w = data[7:0];
    assign x = data[15:8];
    assign y = data[23:16];
    assign z = data[31:24];

endmodule

// Truth Table/State-Transition Table for TopModule:
// Inputs: a[4:0], b[4:0], c[4:0], d[4:0], e[4:0], f[4:0]
// Outputs: w[7:0], x[7:0], y[7:0], z[7:0]
// The output is the concatenation of all inputs followed by two 1s (LSB positions)
// Example:
// Input: a=5'b00000, b=5'b00000, c=5'b00000, d=5'b00000, e=5'b00000, f=5'b00000
// Output: w=8'b00000000, x=8'b00000000, y=8'b00000000, z=8'b00000011

module TopModule (
    input  [4:0] a,
    input  [4:0] b,
    input  [4:0] c,
    input  [4:0] d,
    input  [4:0] e,
    input  [4:0] f,
    output [7:0] w,
    output [7:0] x,
    output [7:0] y,
    output [7:0] z
);

    // Concatenate all input vectors and add two 1s at the LSB
    wire [29:0] data = {a, b, c, d, e, f, 2'b11};

    // Split the 30-bit data into four 8-bit outputs
    assign {w, x, y, z} = {data[29:24], data[23:16], data[15:8], data[7:0]};

endmodule

