module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010
    // 7: 0111
    // 15: 1111
    // SOP expression: a'bc'd + a'bcd + abcd'

    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & !d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110

    // Corrected POS expression:
    // (a + b' + c' + d') * (a + b' + c + d') * (a + b + c' + d') * (a' + b + c + d) * (a' + b + c' + d) * (a' + b' + c + d)

    assign out_pos = (a | (!b | !c | !d)) &
                     (a | (!b | c | !d)) &
                     (a | (b | !c | !d)) &
                     (!a | b | c | d) &
                     (!a | b | !c | d) &
                     (!a | !b | c | d);

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input combinations corresponding to decimal values 2, 7, and 15
    // These are:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1
    assign out_sop = (~a & ~b & c & ~d) | (~a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input combinations corresponding to decimal values 2, 7, and 15
    // So out_pos is 1 for all other valid input combinations (excluding 2, 7, 15)
    // The valid input combinations that should produce out_pos = 1 are:
    // 0, 1, 3, 4, 5, 6, 8, 9, 10, 11, 12, 13, 14
    // The invalid combinations (which should produce out_pos = 0) are 2, 7, 15
    // So out_pos = (a + b + c + d') * (a + b + c' + d) * (a' + b + c + d) * (a' + b + c' + d)

    assign out_pos = (a | b | c | ~d) & (a | b | ~c | d) & (~a | b | c | d) & (~a | b | ~c | d);

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 -> a=0, b=0, c=1, d=0
    // 7: 0111 -> a=0, b=1, c=1, d=1
    // 15: 1111 -> a=1, b=1, c=1, d=1

    // SOP expression: (a' b' c d') + (a' b c d) + (a b c d)
    assign out_sop = (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 1 when 2, 7, or 15 appear
    // So it is 0 for all other values except those three
    // The complement of the SOP expression is the POS expression

    // The SOP expression is: (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d)
    // The complement (POS) is the product of the complements of each term
    // Using De Morgan's Law: (A + B + C)' = A' * B' * C'

    // The complement of the SOP expression is:
    // (!(!a & !b & c & !d)') & (!(!a & b & c & d)') & (! (a & b & c & d)')

    // Simplify each term:
    // 1. (!a & !b & c & !d)' = a + b + !c + d
    // 2. (!a & b & c & d)' = a + !b + !c + !d
    // 3. (a & b & c & d)' = !a + !b + !c + !d

    // So the POS expression is:
    assign out_pos = 
        (a | b | !c | d) &
        (a | !b | !c | !d) &
        (!a | !b | !c | !d);

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk: positive edge-triggered clock
// areset: asynchronous reset (active high)
// train_valid: indicates if training is active
// train_taken: indicates if the branch was taken
//
// Outputs:
// state: 2-bit counter value (0 to 3)
//
// State transitions:
// When areset is high, state is reset to 2'b01 (weakly not-taken)
// When train_valid is 1:
//   if train_taken is 1: increment counter (up to 3)
//   if train_taken is 0: decrement counter (down to 0)
// When train_valid is 0: counter remains unchanged

module TopModule (
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);

    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b01; // reset to weakly not-taken
        end else begin
            if (train_valid) begin
                if (train_taken) begin
                    if (state < 2'b11) begin
                        state <= state + 1;
                    end
                end else begin
                    if (state > 2'b00) begin
                        state <= state - 1;
                    end
                end
            end
        end
    end

endmodule

module TopModule (
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output reg [3:0] out
);

always @(*) begin
    case (sel)
        3'b000: out = data0;
        3'b001: out = data1;
        3'b010: out = data2;
        3'b011: out = data3;
        3'b100: out = data4;
        3'b101: out = data5;
        default: out = 4'b0000;
    endcase
end

endmodule

