module TopModule (
    input  clk,
    input  load,
    input  [9:0] data,
    output reg tc
);

    reg [9:0] counter;

    always @(posedge clk) begin
        if (load) begin
            counter <= data;
            tc <= 1'b0;
        end else begin
            if (counter == 10'd0) begin
                tc <= 1'b1;
            end else begin
                counter <= counter - 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs: clk, load, data[9:0]
// Outputs: tc
//
// State Variables:
// cnt[9:0] - 10-bit down counter
// tc - terminal count signal (1 when cnt == 0)
//
// On each positive edge of clk:
// 1. If load is 1, load cnt with data
// 2. Else, decrement cnt by 1
// 3. If cnt == 0, set tc to 1, else 0
// 4. Once cnt == 0, it remains 0 until loaded again

module TopModule (
    input  clk,
    input  load,
    input  data,
    output reg tc
);

    reg [9:0] cnt;

    always @(posedge clk) begin
        if (load) begin
            cnt <= data;
            tc <= 1'b0;
        end else begin
            if (cnt == 10'b0) begin
                // Already at 0, stay at 0
                tc <= 1'b1;
            end else begin
                cnt <= cnt - 1;
                tc <= 1'b0;
            end
        end
    end

endmodule

