module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Output logic: out is 1 only when in state D
    assign out = state[3]; // D is 4'b1000, so state[3] is 1 when in state D

    // State transition logic
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Use one-hot encoding to derive next_state

    // A (0001)
    // in=0: A (0001), in=1: B (0010)
    // next_state = (in ? 2'b0010 : 2'b0001)

    // B (0010)
    // in=0: C (0100), in=1: B (0010)
    // next_state = (in ? 2'b0010 : 2'b0100)

    // C (0100)
    // in=0: A (0001), in=1: D (1000)
    // next_state = (in ? 2'b1000 : 2'b0001)

    // D (1000)
    // in=0: C (0100), in=1: B (0010)
    // next_state = (in ? 2'b0010 : 2'b0100)

    // Combine all cases using a case statement
    always @(*) begin
        case (state)
            4'b0001: next_state = (in) ? 4'b0010 : 4'b0001; // A
            4'b0010: next_state = (in) ? 4'b0010 : 4'b0100; // B
            4'b0100: next_state = (in) ? 4'b1000 : 4'b0001; // C
            4'b1000: next_state = (in) ? 4'b0010 : 4'b0100; // D
            default: next_state = 4'b0000;
        endcase
    end

endmodule

// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Output is 0 for all states except D (output is 1 when in state D)

    // Output logic: out = state[3] (since D is 4'b1000)
    assign out = state[3];

    // State transition logic (one-hot encoding)
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Using one-hot encoding, only one bit is active at a time

    // State A (state[0] == 1)
    // in=0: next_state = A (state[0] == 1)
    // in=1: next_state = B (state[1] == 1)
    // So: next_state = (state[0] & ~in) ? 1 : (state[0] & in) ? 2 : 0

    // State B (state[1] == 1)
    // in=0: next_state = C (state[2] == 1)
    // in=1: next_state = B (state[1] == 1)
    // So: next_state = (state[1] & ~in) ? 4 : (state[1] & in) ? 2 : 0

    // State C (state[2] == 1)
    // in=0: next_state = A (state[0] == 1)
    // in=1: next_state = D (state[3] == 1)
    // So: next_state = (state[2] & ~in) ? 1 : (state[2] & in) ? 8 : 0

    // State D (state[3] == 1)
    // in=0: next_state = C (state[2] == 1)
    // in=1: next_state = B (state[1] == 1)
    // So: next_state = (state[3] & ~in) ? 4 : (state[3] & in) ? 2 : 0

    // Combine all cases using case statement
    always @(*) begin
        case ({state})
            4'b0001: next_state = (in == 1'b0) ? 4'b0001 : 4'b0010; // A -> A (in=0), B (in=1)
            4'b0010: next_state = (in == 1'b0) ? 4'b0100 : 4'b0010; // B -> C (in=0), B (in=1)
            4'b0100: next_state = (in == 1'b0) ? 4'b0001 : 4'b1000; // C -> A (in=0), D (in=1)
            4'b1000: next_state = (in == 1'b0) ? 4'b0100 : 4'b0010; // D -> C (in=0), B (in=1)
            default: next_state = 4'b0000;
