module TopModule (
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output      out
);

    // State transition logic
    // One-hot encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Determine next state based on current state and input
    // State A (0001)
    assign next_state = (state == 4'b0001) ? 
                        (in ? 4'b0010 : 4'b0001) : // A -> A (in=0), B (in=1)
                      // State B (0010)
                        (state == 4'b0010) ? 
                        (in ? 4'b0010 : 4'b0100) : // B -> B (in=0), C (in=1)
                      // State C (0100)
                        (state == 4'b0100) ? 
                        (in ? 4'b1000 : 4'b0001) : // C -> D (in=0), A (in=1)
                      // State D (1000)
                        (state == 4'b1000) ? 
                        (in ? 4'b0010 : 4'b0100) : // D -> B (in=0), C (in=1)
                      4'b0000; // default case

    // Output logic (Moore machine: output depends only on current state)
    assign out = (state == 4'b1000) ? 1 : 0; // Output is 1 only when in state D

endmodule

