    input  load,
    input  ena,
    input  data,
    output q
);

// Internal signal to hold the 100-bit register
reg [99:0] reg_q;

// Assign output q to the register
assign q = reg_q;

// Always block for synchronous operations
always @(posedge clk) begin
    if (load) begin
        // Load data into the register
        reg_q <= data;
    end else begin
        // Check the enable signal to determine rotation direction
        if (ena == 2'b01) begin
            // Rotate right by one bit
            reg_q <= {reg_q[98:0], reg_q[99]};
        end else if (ena == 2'b10) begin
            // Rotate left by one bit
            reg_q <= {reg_q[0], reg_q[99:1]};
        end
        // No rotation for other values of ena
    end
end

endmodule

// Truth Table/State-Transition Table for TopModule:
// clk is the clock signal (positive edge-triggered)
// load is synchronous active high (loads data into the register)
// ena[1:0] determines the rotation direction:
//   2'b01: rotate right by 1 bit
//   2'b10: rotate left by 1 bit
//   2'b00 or 2'b11: no rotation
// data is the 100-bit input data
// q is the 100-bit output register

// On each positive edge of clk:
// if load is high, q <= data
// else if ena is 2'b01, rotate right by 1 bit
// else if ena is 2'b10, rotate left by 1 bit
// else, q remains the same

module TopModule (
    input  clk,
    input  load,
    input  [1:0] ena,
    input  [99:0] data,
    output [99:0] q
);

    reg [99:0] reg_q;

    always @(posedge clk) begin
        if (load) begin
            reg_q <= data;
        end else begin
            case (ena)
                2'b01: reg_q <= {reg_q[98:0], reg_q[99]}; // rotate right
                2'b10: reg_q <= {reg_q[0], reg_q[98:1]}; // rotate left
                default: reg_q <= reg_q; // no rotation
            endcase
        end
    end

    assign q = reg_q;

endmodule

