    // - When c=1 and (a=1, b=1, d=1)
    // - When c=0 and (a=0, b=0, d=0) → this is a don't care

    // The correct expression is:
    assign out = (c & (a | b)) | (a & b) | (a & d) | (b & d) | (c & (a ^ b)) | (c & d);

