    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Local variables for neighbor count
    reg [7:0] neighbor_count;

    // Function to compute the number of live neighbors for a given cell
    function [7:0] count_neighbors;
        input [7:0] row;
        input [7:0] col;
        begin
            count_neighbors = 0;
            for (int i = -1; i <= 1; i = i + 1) begin
                for (int j = -1; j <= 1; j = j + 1) begin
                    if (i == 0 && j == 0) continue;
                    int r = (row + i) % 16;
                    int c = (col + j) % 16;
                    if (current_q[(r * 16) + c]) count_neighbors = count_neighbors + 1;
                end
            end
        end
    endfunction

    // Function to compute the next state of a cell based on neighbor count
    function [0:0] next_state;
        input [7:0] neighbors;
        begin
            if (neighbors == 2) next_state = current_q[0];
            else if (neighbors == 3) next_state = 1;
            else next_state = 0;
        end
    endfunction

    // Compute next state for all cells
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            for (int i = 0; i < 16; i = i + 1) begin
                for (int j = 0; j < 16; j = j + 1) begin
                    int r = i;
                    int c = j;
                    neighbor_count = count_neighbors(r, c);
                    next_q[(r * 16) + c] <= next_state(neighbor_count);
                end
            end
            current_q <= next_q;
        end
    end

    // Output the current state
    assign q = current_q;

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal register to hold the next state
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state based on current state (q)
    always @(*) begin
        next_q = 256'b0;

        for (integer i = 0; i < 256; i = i + 1) begin
            // Current cell
            reg current_cell = q[i];
            // Count number of live neighbors
            integer neighbor_count = 0;

            // Check all 8 neighbors (toroidal)
            for (integer dx = -1; dx <= 1; dx = dx + 1) begin
                for (integer dy = -1; dy <= 1; dy = dy + 1) begin
                    if (dx == 0 && dy == 0) continue; // Skip current cell

                    integer row = (i / 16 + dx) % 16;
                    integer col = (i % 16 + dy) % 16;
                    integer neighbor_index = row * 16 + col;

                    if (q[neighbor_index]) neighbor_count = neighbor_count + 1;
                end
            end

            // Apply Game of Life rules
            if (neighbor_count < 2) begin
                next_q[i] = 1'b0;
            end else if (neighbor_count == 2) begin
                next_q[i] = current_cell;
            end else if (neighbor_count == 3) begin
                next_q[i] = 1'b1;
            end else begin
                next_q[i] = 1'b0;
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal register to hold the next state
    reg [255:0] next_q;

    // Declare variables at module level
    reg [3:0] neighbors;
    integer i, j, k, count;

    // Determine the next state based on current state q
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            // Compute next state
            next_q <= 256'b0;

            for (i = 0; i < 16; i = i + 1) begin
                for (j = 0; j < 16; j = j + 1) begin
                    // Calculate the 8 neighbors of cell (i,j)
                    count = 0;
                    for (k = 0; k < 8; k = k + 1) begin
                        integer dx, dy;
                        case (k)
                            0: {dx, dy} = {1, 1};
                            1: {dx, dy} = {1, 0};
                            2: {dx, dy} = {1, -1};
                            3: {dx, dy} = {0, 1};
                            4: {dx, dy} = {0, -1};
                            5: {dx, dy} = {-1, 1};
                            6: {dx, dy} = {-1, 0};
                            7: {dx, dy} = {-1, -1};
                        endcase

                        integer x = (i + dx) % 16;
                        integer y = (j + dy) % 16;
                        integer pos = x * 16 + y;
                        if (q[pos]) count = count + 1;
                    end

                    // Apply Conway's Game of Life rules
                    if (count == 2) begin
                        next_q[i*16 + j] = q[i*16 + j];
                    end else if (count == 3) begin
                        next_q[i*16 + j] = 1;
                    end else begin
                        next_q[i*16 + j] = 0;
                    end
                end
            end
            q <= next_q;
        end
    end

endmodule

module TopModule (
    input  clock,
    input  a,
    output p,
    output q
);

    reg p_reg, q_reg, next_p, next_q;

    always @(posedge clock) begin
        p_reg <= next_p;
        q_reg <= next_q;
    end

    // Determine next state based on current state and input a
    assign next_p = (p_reg == 1'b0 && a == 1'b1) ? 1'b1 : (p_reg == 1'b1 && a == 1'b0) ? 1'b0 : p_reg;
    assign next_q = (q_reg == 1'b0 && a == 1'b1) ? 1'b1 : (q_reg == 1'b1 && a == 1'b0) ? 1'b0 : q_reg;

    assign p = p_reg;
    assign q = q_reg;

endmodule

